<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Throwable; use Aternos\Nbt\Tag\CompoundTag; use Illuminate\Support\Facades\Cache; class Worlds { private const LIST_TTL = 60; private const DETAIL_TTL = 300; public const NEVER = [ 'plugins', 'mods', 'libraries', 'logs', 'cache', 'config', 'defaultconfigs', 'crash-reports', 'versions', 'bluemap', 'backups', 'resourcepacks', 'datapacks', 'kubejs', 'schematics', 'dynmap', 'plugin_data', 'local', ]; private const MAX_LEVEL_DAT = 4_000_000; public static function list(ServerFiles $files, string $server): array { return Cache::remember( "dezerx:worlds:{$server}", self::LIST_TTL, fn () => self::build($files), ); } private static function build(ServerFiles $files): array { $root = $files->listFiles('/'); if ($root === null) { return ['available' => false, 'active' => null, 'worlds' => []]; } $candidates = []; foreach ($root as $entry) { $name = (string) ($entry['name'] ?? ''); if (!($entry['directory'] ?? false) || str_starts_with($name, '.') || in_array(mb_strtolower($name), self::NEVER, true)) { continue; } $candidates["/{$name}"] = $entry; } $active = self::activeLevel($files); $listings = $files->listFilesMany(array_keys($candidates)); $worlds = []; foreach ($candidates as $path => $entry) { $names = array_column($listings[$path] ?? [], 'name'); if (!in_array('level.dat', $names, true)) { continue; } $name = (string) ($entry['name'] ?? ''); $worlds[] = [ 'name' => $name, 'path' => $path, 'hasPlayers' => in_array('playerdata', $names, true), 'hasNether' => in_array('DIM-1', $names, true), 'hasEnd' => in_array('DIM1', $names, true), 'modifiedAt' => $entry['modified_at'] ?? null, 'active' => $name === $active, ]; } usort($worlds, fn (array $a, array $b) => [!$a['active'], mb_strtolower($a['name'])] <=> [!$b['active'], mb_strtolower($b['name'])]); return ['available' => true, 'active' => $active, 'worlds' => $worlds]; } public static function details(ServerFiles $files, string $server, string $world): array { return Cache::remember( "dezerx:world:{$server}:".sha1($world), self::DETAIL_TTL, function () use ($files, $world) { $dimensions = self::dimensions($files, $world); $size = 0; $regions = 0; foreach ($files->listFilesMany(array_column($dimensions, 'path')) as $rows) { foreach ($rows ?? [] as $entry) { if (preg_match('/^r\.-?\d+\.-?\d+\.mca$/', (string) ($entry['name'] ?? '')) !== 1) { continue; } $regions++; $size += (int) ($entry['size'] ?? 0); } } return [ 'dimensions' => $dimensions, 'size' => $size, 'regions' => $regions, 'players' => self::playerCount($files, $world), 'level' => self::level($files, $world), ]; }, ); } public static function dimensions(ServerFiles $files, string $world): array { $names = array_column($files->listFiles($world) ?? [], 'name'); $found = []; if (in_array('region', $names, true)) { $found[] = ['name' => 'Overworld', 'path' => "{$world}/region"]; } foreach (['DIM-1' => 'Nether', 'DIM1' => 'The End'] as $folder => $label) { if (in_array($folder, $names, true)) { $found[] = ['name' => $label, 'path' => "{$world}/{$folder}/region"]; } } if (!in_array('dimensions', $names, true)) { return $found; } $namespaces = self::directories($files->listFiles("{$world}/dimensions")); $candidates = []; foreach ($files->listFilesMany(array_map( fn (string $space) => "{$world}/dimensions/{$space}", $namespaces, )) as $space => $rows) { foreach (self::directories($rows) as $dimension) { $candidates[] = "{$space}/{$dimension}"; } } foreach ($files->listFilesMany($candidates) as $path => $rows) { if (!in_array('region', array_column($rows ?? [], 'name'), true)) { continue; } [$space, $dimension] = array_slice(explode('/', $path), -2); $found[] = [ 'name' => match ("{$space}:{$dimension}") { 'minecraft:overworld' => 'Overworld', 'minecraft:the_nether' => 'Nether', 'minecraft:the_end' => 'The End', default => "{$space}:{$dimension}", }, 'path' => "{$path}/region", ]; } return $found; } private static function playerCount(ServerFiles $files, string $world): int { $count = 0; foreach ($files->listFiles("{$world}/playerdata") ?? [] as $entry) { if (str_ends_with((string) ($entry['name'] ?? ''), '.dat')) { $count++; } } return $count; } private static function level(ServerFiles $files, string $world): ?array { $raw = $files->fileContents("{$world}/level.dat", self::MAX_LEVEL_DAT); if ($raw === null) { return null; } try { [$plain] = Nbt::decompress($raw); $tag = Nbt::parse($plain); } catch (Throwable) { return null; } $data = $tag instanceof CompoundTag ? $tag->get('Data') : null; if (!$data instanceof CompoundTag) { return null; } $version = $data->get('Version'); $lastPlayed = $data->getLong('LastPlayed')?->getValue(); $settings = $data->get('difficulty_settings'); $settings = $settings instanceof CompoundTag ? $settings : null; return [ 'name' => $data->getString('LevelName')?->getValue(), 'version' => $version instanceof CompoundTag ? $version->getString('Name')?->getValue() : null, 'seed' => self::seed($data), 'hardcore' => (bool) ( $data->getByte('hardcore')?->getValue() ?? $settings?->getByte('hardcore')?->getValue() ?? 0 ), 'difficulty' => self::difficulty($data, $settings), 'gameType' => $data->getInt('GameType')?->getValue(), 'spawn' => self::spawn($data), 'lastPlayed' => $lastPlayed !== null && $lastPlayed > 0 ? date(DATE_ATOM, intdiv((int) $lastPlayed, 1000)) : null, ]; } private static function difficulty(CompoundTag $data, ?CompoundTag $settings): ?string { $name = $settings?->getString('difficulty')?->getValue(); if ($name !== null && $name !== '') { return $name; } return match ($data->getByte('Difficulty')?->getValue()) { 0 => 'peaceful', 1 => 'easy', 2 => 'normal', 3 => 'hard', default => null, }; } private static function spawn(CompoundTag $data): ?array { $x = $data->getInt('SpawnX')?->getValue(); if ($x !== null) { return [ 'x' => (int) $x, 'y' => (int) ($data->getInt('SpawnY')?->getValue() ?? 0), 'z' => (int) ($data->getInt('SpawnZ')?->getValue() ?? 0), ]; } $spawn = $data->get('spawn'); $pos = $spawn instanceof CompoundTag ? $spawn->getIntArray('pos') : null; if ($pos === null) { return null; } $values = []; foreach ($pos as $value) { $values[] = (int) $value; } return count($values) === 3 ? ['x' => $values[0], 'y' => $values[1], 'z' => $values[2]] : null; } private static function seed(CompoundTag $data): ?string { $settings = $data->get('WorldGenSettings'); $seed = $settings instanceof CompoundTag ? $settings->getLong('seed')?->getValue() : null; $seed ??= $data->getLong('RandomSeed')?->getValue(); return $seed === null ? null : (string) $seed; } public static function activeLevel(ServerFiles $files): ?string { $properties = ServerProperties::read($files); if ($properties === null) { return null; } $name = trim($properties['level-name'] ?? ''); return $name === '' ? null : $name; } public static function forget(string $server, ?string $world = null): void { Cache::forget("dezerx:worlds:{$server}"); if ($world !== null) { Cache::forget("dezerx:world:{$server}:".sha1($world)); } } private static function directories(?array $rows): array { $names = []; foreach ($rows ?? [] as $row) { if ($row['directory'] ?? false) { $names[] = (string) ($row['name'] ?? ''); } } return $names; } public static function safePath(string $path): ?string { $path = '/'.ltrim(trim($path), '/'); if (str_contains($path, '..') || str_contains($path, "\0")) { return null; } return rtrim($path, '/') ?: null; } public static function worldName(string $path): ?string { $safe = self::safePath($path); if ($safe === null || substr_count($safe, '/') !== 1) { return null; } $name = substr($safe, 1); return $name === '' || in_array(mb_strtolower($name), self::NEVER, true) ? null : $name; } } 